        set:@"terrainLightingEnabled" value:@YES]
        set:@"sunAzimuth" value:@315]
        set:@"sunAltitude" value:@42]
        set:@"shadowStrength" value:@1.0]
        set:@"shadowSoftness" value:@1.5] error:nil];

