        double current = [map.terrain getDouble:@"exaggeration" defaultValue:1];
        [map.terrain set:@"exaggeration" value:@(current >= 2 ? 1.0 : current + 0.35)];
    }];
    [host caption:@"The Matterhorn. Imagery on the mesh, roads and summits above it."];
}

