    return @[
        @[ @"Mont Blanc",       @6.8652, @45.8326, @4808 ],
        @[ @"Grandes Jorasses", @6.9866, @45.8697, @4208 ],
        @[ @"Aiguille Verte",   @6.9256, @45.9036, @4122 ],
        @[ @"Mont Dolent",      @7.0575, @45.9264, @3820 ],
    ];
